ps.pstext:
if !IsFeatureImplemented(FEAT_CFLT) then EndOfDecode(Decode_UNDEF); end;
let datasize : integer{} = 32 << UInt(sf);
let t : integer = UInt(Rt);
let imm : bits(9) = imm9h::imm9l;
let reason : bits(16) = ZeroExtend{}(imm2);

var cmp : CmpOp;
var unsigned : boolean;

case cc of
    when '000' => cmp = Cmp_GT; unsigned = FALSE;
    when '001' => cmp = Cmp_LT; unsigned = FALSE;
    when '010' => cmp = Cmp_GT; unsigned = TRUE;
    when '011' => cmp = Cmp_LT; unsigned = TRUE;
    when '100' => cmp = Cmp_EQ; unsigned = FALSE;
    when '101' => cmp = Cmp_NE; unsigned = FALSE;
    otherwise  => EndOfDecode(Decode_UNDEF);
end;

CheckCFLTEnabled();

let operand1 : bits(datasize) = X{}(t);

var cond : boolean;
let value1 : integer = if unsigned then UInt(operand1) else SInt(operand1);
let value2 : integer = if unsigned then UInt(imm) else SInt(imm);

case cmp of
    when Cmp_EQ => cond = value1 == value2;
    when Cmp_NE => cond = value1 != value2;
    when Cmp_LT => cond = value1 < value2;
    when Cmp_GT => cond = value1 > value2;
end;
if cond then
    let isflt : boolean = FALSE;
    AArch64_ConditionalFault(isflt, reason);
end;
